CREATE SCHEMA nicar;

REVOKE ALL ON SCHEMA nicar FROM PUBLIC, anon, authenticated;

CREATE TABLE nicar."Marca" (
    "IdMarca" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" varchar(60) NOT NULL,
    "PaisOrigen" varchar(60),
    "Activo" boolean NOT NULL,
    UNIQUE ("Nombre")
);

CREATE TABLE nicar."Modelo" (
    "IdModelo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdMarca" integer NOT NULL REFERENCES nicar."Marca"("IdMarca"),
    "Nombre" varchar(80) NOT NULL,
    "Activo" boolean NOT NULL,
    UNIQUE ("IdMarca", "Nombre")
);

CREATE TABLE nicar."Vehiculo" (
    "IdVehiculo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdModelo" integer NOT NULL REFERENCES nicar."Modelo"("IdModelo"),
    "IdentificadorUnico" varchar(50) NOT NULL,
    "VIN" varchar(17),
    "NumeroChasis" varchar(50),
    "Placa" varchar(10),
    "EstadoMatricula" varchar(20) NOT NULL,
    "Anio" smallint NOT NULL,
    "Version" varchar(80),
    "ColorExterior" varchar(40) NOT NULL,
    "ColorInterior" varchar(40),
    "Transmision" varchar(20) NOT NULL,
    "Traccion" varchar(15) NOT NULL,
    "Combustible" varchar(20) NOT NULL,
    "Kilometraje" bigint NOT NULL,
    "TipoCarroceria" varchar(30) NOT NULL,
    "Estado" varchar(25) NOT NULL,
    "FechaRegistro" timestamp NOT NULL,
    "Observaciones" varchar(500),
    "PrecioOferta" numeric(18,2),
    "ImagenUrl" varchar(500),
    "Ubicacion" varchar(80),
    "Activo" boolean NOT NULL,
    UNIQUE ("IdentificadorUnico"),
    UNIQUE ("VIN"),
    UNIQUE ("NumeroChasis"),
    UNIQUE ("Placa")
);

CREATE TABLE nicar."Cliente" (
    "IdCliente" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TipoCliente" varchar(20) NOT NULL,
    "Nombres" varchar(100),
    "Apellidos" varchar(100),
    "RazonSocial" varchar(150),
    "TipoIdentificacion" varchar(10) NOT NULL,
    "NumeroIdentificacion" varchar(30) NOT NULL,
    "Telefono" varchar(20),
    "Correo" varchar(120),
    "Direccion" varchar(300),
    "FechaRegistro" timestamp NOT NULL,
    "Activo" boolean NOT NULL,
    UNIQUE ("TipoIdentificacion", "NumeroIdentificacion")
);

CREATE TABLE nicar."Proveedor" (
    "IdProveedor" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TipoProveedor" varchar(30) NOT NULL,
    "NombreProveedor" varchar(150) NOT NULL,
    "IdentificacionFiscal" varchar(30),
    "Pais" varchar(60) NOT NULL,
    "Ciudad" varchar(80),
    "Direccion" varchar(250),
    "Telefono" varchar(20),
    "Correo" varchar(120),
    "Contacto" varchar(120),
    "FechaRegistro" timestamp NOT NULL,
    "Observaciones" varchar(500),
    "Activo" boolean NOT NULL,
    UNIQUE ("IdentificacionFiscal")
);

CREATE TABLE nicar."TipoCosto" (
    "IdTipoCosto" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" varchar(80) NOT NULL,
    "Descripcion" varchar(200),
    "Activo" boolean NOT NULL
);

CREATE TABLE nicar."AdquisicionVehiculo" (
    "IdAdquisicion" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdVehiculo" integer NOT NULL REFERENCES nicar."Vehiculo"("IdVehiculo"),
    "IdProveedor" integer NOT NULL REFERENCES nicar."Proveedor"("IdProveedor"),
    "FechaAdquisicion" date NOT NULL,
    "PrecioCompra" numeric(18,2) NOT NULL,
    "Moneda" varchar(3) NOT NULL,
    "TasaCambio" numeric(18,6) NOT NULL,
    "PrecioCompraNIO" numeric(18,2) GENERATED ALWAYS AS (CASE WHEN "Moneda" = 'USD' THEN "PrecioCompra" * "TasaCambio" ELSE "PrecioCompra" END) STORED
);

CREATE TABLE nicar."CostoVehiculo" (
    "IdCosto" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdVehiculo" integer NOT NULL REFERENCES nicar."Vehiculo"("IdVehiculo"),
    "IdTipoCosto" integer NOT NULL REFERENCES nicar."TipoCosto"("IdTipoCosto"),
    "Descripcion" varchar(200) NOT NULL,
    "FechaCosto" date NOT NULL,
    "Monto" numeric(18,2) NOT NULL,
    "Moneda" varchar(3) NOT NULL,
    "TasaCambio" numeric(18,6) NOT NULL,
    "MontoNIO" numeric(18,2),
    "NumeroDocumento" varchar(80),
    "Observaciones" varchar(300),
    "Activo" boolean NOT NULL
);

CREATE TABLE nicar."Venta" (
    "IdVenta" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdVehiculo" integer NOT NULL REFERENCES nicar."Vehiculo"("IdVehiculo"),
    "IdCliente" integer NOT NULL REFERENCES nicar."Cliente"("IdCliente"),
    "NumeroComprobante" varchar(30) NOT NULL,
    "FechaVenta" date NOT NULL,
    "PrecioVenta" numeric(18,2) NOT NULL,
    "Descuento" numeric(18,2) NOT NULL,
    "Total" numeric(18,2) GENERATED ALWAYS AS ("PrecioVenta" - "Descuento") STORED,
    "Moneda" varchar(3) NOT NULL,
    "MetodoPago" varchar(30) NOT NULL,
    "ReferenciaPago" varchar(80),
    "Observaciones" varchar(500),
    "UsuarioRegistro" varchar(80),
    "Activa" boolean NOT NULL,
    UNIQUE ("IdVehiculo"),
    UNIQUE ("NumeroComprobante"),
    CHECK ("PrecioVenta" > 0 AND "Descuento" BETWEEN 0 AND "PrecioVenta"),
    CHECK ("Moneda" IN ('USD','NIO')),
    CHECK ("MetodoPago" IN ('Efectivo','Transferencia','Tarjeta','Financiamiento'))
);

CREATE TABLE nicar."Usuario" (
    "IdUsuario" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NombreUsuario" text NOT NULL UNIQUE,
    "NombreCompleto" text NOT NULL,
    "Rol" text NOT NULL CHECK ("Rol" IN ('SuperAdministrador','Administrador','Vendedor','Bodega','Recepcionista')),
    "HashContrasena" text NOT NULL,
    "Salt" text NOT NULL,
    "Activo" boolean NOT NULL DEFAULT true,
    "IntentosFallidos" integer NOT NULL DEFAULT 0,
    "BloqueadoHasta" timestamp,
    "DebeCambiarContrasena" boolean NOT NULL DEFAULT true,
    "FechaCreacion" timestamp NOT NULL DEFAULT localtimestamp
);

CREATE TABLE nicar."LogAcceso" (
    "IdLog" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdUsuario" integer REFERENCES nicar."Usuario",
    "NombreIngresado" text,
    "Evento" text NOT NULL,
    "FechaHora" timestamp NOT NULL DEFAULT localtimestamp
);

CREATE INDEX ON nicar."Vehiculo" ("Estado");

CREATE INDEX ON nicar."Vehiculo" ("IdModelo");

CREATE INDEX ON nicar."Venta" ("FechaVenta");

CREATE INDEX ON nicar."Venta" ("IdCliente");

CREATE INDEX ON nicar."AdquisicionVehiculo" ("IdProveedor");

CREATE INDEX ON nicar."AdquisicionVehiculo" ("IdVehiculo");

CREATE INDEX ON nicar."CostoVehiculo" ("IdVehiculo");

CREATE INDEX ON nicar."CostoVehiculo" ("IdTipoCosto");

CREATE INDEX ON nicar."LogAcceso" ("IdUsuario");
